raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBGL-S2-R07-01",
   "status": "OK",
   "label": "이자 지급시기",
   "source": {
    "quote": "▪ 매년 2월, 5월, 8월, 11월의 둘째 금요일에 결산하여 다음날 원금에 더함"
   },
   "condition": {
    "in": [
     {
      "var": "account.last_transaction_date"
     },
     [
      {
       "month_of": 2,
       "day": {
        "weekday": "FRI",
        "nth": 2
       }
      },
      {
       "month_of": 5,
       "day": {
        "weekday": "FRI",
        "nth": 2
       }
      },
      {
       "month_of": 8,
       "day": {
        "weekday": "FRI",
        "nth": 2
       }
      },
      {
       "month_of": 11,
       "day": {
        "weekday": "FRI",
        "nth": 2
       }
      }
     ]
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "INTEREST_CALCULATED"
   }
  },
  {
   "rule_id": "R-KBGL-S2-R07-02",
   "status": "OK",
   "label": "이자 계산 시점 변경",
   "source": {
    "quote": "※ 예금의 이자는 최종거래일로부터 5년이 경과한 날부터는 이자를 원금에 더하지 않고, 계좌해지 또는 추가 입출금 거래 발생일에 일괄 계산하여 지급할 수 있습니다"
   },
   "condition": {
    ">=": [
     {
      "var": "account.last_transaction_date"
     },
     {
      "anchor": "account.opening_date",
      "offset_months": 60
     }
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "INTEREST_CALCULATED_ON_TRANSACTION"
   }
  }
 ]
}

