   "source": {
    "quote": "▪ 대상수수료 (이 통장 거래 기준) • 전자금융(인터넷뱅킹, 폰뱅킹, 모바일뱅킹) 이체수수료(다른 은행으로 보낼 때)(※납부자자동이체 제외) 및 KB국민은행 자동화기기 시간외출금수수료"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "exists": {
     "event": "AUTO_TRANSFER",
     "within": {
      "ref": "$window"
     },
     "where": {
      "not": {
       "in": [
        {
         "var": "AUTO_TRANSFER.route"
        },
        [
         "APARTMENT_FEE",
         "GIRO",
         "CMS",
         "FIRM_BANKING",
         "CARD"
        ]
       ]
      }
     }
    },
    "or": [
